import fs from 'node:fs/promises';
const fixture = JSON.parse(await fs.readFile(new URL('./fixtures/legacy-desks-v0891.json', import.meta.url), 'utf8'));

// Generated by the previous implementation, before its creation paths retired.
// Only synthetic tests can append these exact historical desk records.
export async function addLegacyDesk(f, kind, name) {
  const item = structuredClone(fixture.desks[kind]);
  if (!item) throw new Error('Unknown legacy fixture');
  if (name) item.root.name = name;
  await f.app.store.transact(state => {
    state.roots.push(item.root); state.chats.push(item.chat);
    state.ui.mode = item.root.mode;
    state.ui.selected[item.root.mode] = { rootId: item.root.id, chatId: item.chat.id };
    return state;
  });
  return item;
}
